import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md","lastUpdated":1790164074000}'),r={name:"compatibility.md"};function n(c,e,i,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>What runs where, what converts in which direction, and what does not (yet). Everything here is exercised by the test suites under <code>python/</code> and <code>tests/</code>.</p><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to &quot;Backends&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>How</th><th>Runs the model on</th><th>Notes</th></tr></thead><tbody><tr><td>PyTorch</td><td><code>linnet_torch.load</code> → <code>torch.nn.Module</code></td><td>CPU, CUDA (any device PyTorch has)</td><td>Core IR interpreted on index grids, or with <code>compile=True</code> run as straight-line PyTorch source from <code>linnet torch</code> (<code>compile=&quot;inductor&quot;</code> adds <code>torch.compile</code>); <code>numerics=&quot;equivalent&quot;</code> selects native kernels for library ops (<code>matmul</code>, <code>softmax</code>, <code>layer_norm</code>, <code>rms_norm</code>, <code>attention</code>, activations). <code>state</code> members are non-persistent buffers.</td></tr><tr><td>JAX</td><td><code>linnet_jax.load</code> → callable, <code>load_nnx</code> → Flax NNX module</td><td>Any XLA backend (CPU, GPU, TPU)</td><td>Compiles through <code>linnet stablehlo</code>; composes with <code>jax.jit</code>. Inference only (no VJP). <code>state</code> is threaded: <code>f(*inputs, state=...) -&gt; (out, new_state)</code>.</td></tr><tr><td>XLA / StableHLO</td><td><code>linnet stablehlo --bind ...</code></td><td>Anything that consumes StableHLO</td><td>Static shapes per binding; <code>@main</code> with parameters named by <code>linnet.path</code>, state by <code>linnet.state</code> / <code>linnet.states</code>.</td></tr><tr><td>ONNX</td><td><code>linnet onnx --bind ...</code> → ONNX text format</td><td>ONNX Runtime and other ONNX consumers</td><td>opset 20; parameters as <code>param&lt;N&gt;</code> inputs with <code>linnet.path.*</code> metadata; state as <code>state&lt;N&gt;</code> / <code>next_state&lt;N&gt;</code>.</td></tr></tbody></table><h2 id="importers" tabindex="-1">Importers <a class="header-anchor" href="#importers" aria-label="Permalink to &quot;Importers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>How</th><th>Recovers</th></tr></thead><tbody><tr><td>PyTorch modules</td><td><code>linnet_torch.export_linnet(module, inputs)</code> via <code>torch.export</code></td><td>Module hierarchy as blocks and sub arrays; <code>nn.Linear</code>, <code>Embedding</code>, <code>LayerNorm</code>, <code>RMSNorm</code>, softmax, GELU, SiLU as library calls; index notation for <code>matmul</code>/<code>einsum</code>; SafeTensors weights by path.</td></tr><tr><td>JAX functions</td><td><code>linnet_jax.export_linnet(fn, params, inputs)</code> via <code>jax.export</code></td><td>The parameter pytree as blocks (lists and <code>0..n-1</code> dicts as sub arrays); <code>dot_general</code>, <code>reduce</code>, <code>gather</code> rows, <code>broadcast_in_dim</code>; decompositions of <code>jax.nn.softmax</code>, <code>sigmoid</code>, <code>silu</code>, tanh-<code>gelu</code>, and <code>rsqrt(mean(x*x)+eps)</code> RMS norms as library calls.</td></tr><tr><td>StableHLO text</td><td><code>linnet_jax.import_stablehlo(text, params)</code></td><td>Same translator as above, for modules produced elsewhere; parameters may be <code>jax.ShapeDtypeStruct</code>s.</td></tr><tr><td>ONNX models</td><td><code>linnet_onnx.import_onnx(model)</code></td><td>Initializer names as the block hierarchy; <code>dim_param</code>s as generics; shape arithmetic folded at import; <code>Softmax</code>, <code>LayerNormalization</code>, <code>Gelu</code>, <code>Sigmoid</code>, <code>Relu</code>, <code>MatMul</code>, <code>Gemm</code>, <code>Reduce*</code>, <code>Gather</code>, <code>Slice</code>, ...; PyTorch&#39;s decomposed RMS norm, SiLU, and softmax recovered.</td></tr></tbody></table><p>Every importer refuses rather than guesses: an operation without a Linnet mapping stops the import with a message naming it, and anything dropped on the way (a NaN guard Linnet does not need) is reported in <code>notes</code>.</p><h2 id="round-trips" tabindex="-1">Round trips <a class="header-anchor" href="#round-trips" aria-label="Permalink to &quot;Round trips&quot;">​</a></h2><p>The same <code>.linnet</code> file produces matching outputs (within 1e-4 in f32) in PyTorch eager, XLA, JAX, and ONNX Runtime, and a model exported from PyTorch or JAX, written as Linnet, and loaded back agrees with the original. These are the <code>test_round_trip</code> / <code>test_export</code> / <code>test_import</code> suites.</p><h2 id="language-features-by-backend" tabindex="-1">Language features by backend <a class="header-anchor" href="#language-features-by-backend" aria-label="Permalink to &quot;Language features by backend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>PyTorch</th><th>JAX / StableHLO</th><th>ONNX</th></tr></thead><tbody><tr><td>Symbolic shapes</td><td>bound at load, entry generics from inputs</td><td>bound per compile (<code>--bind</code>, or from inputs at call)</td><td>bound per export</td></tr><tr><td><code>static for</code> over sub arrays and integer ranges</td><td>✓</td><td>✓ (unrolled)</td><td>✓ (unrolled)</td></tr><tr><td><code>while</code> (runtime loop, scalar <code>bool</code> condition)</td><td>✓ (also in generated source)</td><td>✓ <code>stablehlo.while</code></td><td>✓ <code>Loop</code></td></tr><tr><td>Index notation, reductions</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>Optional parameters (<code>= none</code>)</td><td>✓</td><td>✓ (<code>--optionals</code>)</td><td>✓</td></tr><tr><td>Enum-typed constants and <code>match</code></td><td>✓</td><td>✓ (folded)</td><td>✓ (folded)</td></tr><tr><td>Tuple results</td><td>✓</td><td>✓</td><td>✓ (one output per element)</td></tr><tr><td><code>state</code> members</td><td>✓ buffers, <code>reset_state()</code></td><td>✓ threaded in/out</td><td>✓ threaded in/out</td></tr><tr><td><code>std.random</code> (keyed Threefry PRNG)</td><td>✓</td><td>✓</td><td>✓ (right shifts are logical)</td></tr><tr><td>dtypes</td><td>f16, bf16, f32, f64, i8–i64, u8, bool</td><td>as the backend supports</td><td>as opset 20 supports</td></tr></tbody></table><h2 id="not-supported-yet" tabindex="-1">Not supported (yet) <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported (yet)&quot;">​</a></h2><ul><li>A <code>scan</code> that collects per-iteration outputs, and data-dependent shapes. <code>while</code> covers data-dependent loops with invariant shapes (the Llama example&#39;s <code>generate_until</code> stops at an end token) on every backend.</li><li>Randomness is a library, not a primitive: <code>std.random</code> (Threefry-2x32, matching <code>jax.random</code> bit for bit) runs on every backend; there is no hidden generator state.</li><li>Training in JAX: the materialized function has no VJP yet. In PyTorch, <code>load(..., trainable=True)</code> trains through autograd (interpreted or as generated source).</li><li>Quantized <em>dtypes</em>: quantization is library code (<code>std.quant</code>: per-row int8 and packed int4 weights with scales, <code>Int8Linear</code>/<code>Int4Linear</code>), not a storage type; per-group and asymmetric schemes are not written yet.</li><li>Importers: <code>erf</code>-based GELU (no <code>erf</code> primitive), softmax over an axis other than the last, general <code>gather</code>/scatter, custom calls.</li></ul><p>The <a href="https://github.com/franknoh/Linnet#readme" target="_blank" rel="noreferrer">roadmap</a> tracks these; state threading is the first of the milestone-16 features (state, RNG, loops, training, quantization) and landed with the <code>decode</code> entry of the <a href="/examples/05-llama">Llama example</a>.</p>',14)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
